<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\ValueObject\Holder\TenantTermsOfUseAttachedAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantTermsOfUseAttachedAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantTermsOfUseAttachedAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getAttached returns null on a freshly created holder.
     */
    public function testAttachedNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantTermsOfUseAttachedAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isAttachedAssigned());
        $this->assertNull($holder->getAttached());
    }
}
class ImplWithTenantTermsOfUseAttachedAttributeHolderUnitTest
{
    use TenantTermsOfUseAttachedAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedAttachedRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultAttached();
    }
}
